body.script:
//
(function() {
    'use strict';

    // Dynamic Footer Year
    var yearEl = document.getElementById('current-year');
    if (yearEl) {
        yearEl.textContent = new Date().getFullYear();
    }

    // Calculate Reading Time
    function calculateReadingTimes() {
        var elements = document.querySelectorAll('.read-time-output');
        elements.forEach(function(el) {
            var text = el.getAttribute('data-body') || el.innerText || '';
            var cleanText = text.replace(/<[^>]*>/g, '');
            var words = cleanText.trim().split(/\s+/).length;
            var wpm = 200;
            var minutes = Math.ceil(words / wpm);
            if (minutes < 1) minutes = 1;
            el.textContent = minutes;
        });
    }

    // Dynamic External Thumbnail Parser
    function parseExternalThumbnails() {
        var posts = document.querySelectorAll('.post-item');
        posts.forEach(function(post) {
            var placeholder = post.querySelector('.post-thumbnail-placeholder');
            var thumbLink = post.querySelector('.external-thumb-link');
            var thumbImg = post.querySelector('.external-thumb-img');
            var snippetBody = post.querySelector('.post-snippet-body');

            if (snippetBody && thumbImg && placeholder) {
                var tempDiv = document.createElement('div');
                tempDiv.innerHTML = snippetBody.innerHTML;
                var firstImg = tempDiv.querySelector('img');

                if (firstImg && firstImg.src) {
                    thumbImg.src = firstImg.src;
                    thumbLink.classList.remove('hidden');
                    placeholder.style.display = 'none';
                }
            }
        });
    }

    // Mobile Menu
    var menuToggle = document.getElementById('menuToggle');
    var mobileMenu = document.getElementById('mobileMenu');
    if (menuToggle && mobileMenu) {
        menuToggle.addEventListener('click', function() {
            mobileMenu.classList.toggle('hidden');
        });
    }

    // Search Modal Toggle
    var searchToggle = document.getElementById('searchToggle');
    var searchToggleMobile = document.getElementById('searchToggleMobile');
    var searchModal = document.getElementById('searchModal');
    var searchClose = document.getElementById('searchClose');
    var searchInput = document.getElementById('searchInput');
    var searchResults = document.getElementById('searchResults');

    function openSearch() {
        searchModal.classList.add('active');
        setTimeout(function() { searchInput.focus(); }, 100);
    }

    function closeSearch() {
        searchModal.classList.remove('active');
        searchInput.value = '';
        searchResults.innerHTML = '';
    }

    if (searchToggle) searchToggle.addEventListener('click', openSearch);
    if (searchToggleMobile) searchToggleMobile.addEventListener('click', openSearch);
    if (searchClose) searchClose.addEventListener('click', closeSearch);

    document.addEventListener('keydown', function(e) {
        if (e.key === 'Escape') closeSearch();
        if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
            e.preventDefault();
            if (searchModal.classList.contains('active')) {
                closeSearch();
            } else {
                openSearch();
            }
        }
    });

    if (searchModal) {
        searchModal.addEventListener('click', function(e) {
            if (e.target === this) closeSearch();
        });
    }

    // Search Logic
    var allPosts = [];

    function fetchAllPosts() {
        fetch('/feeds/posts/summary?alt=json&max-results=150')
            .then(function(response) { return response.json(); })
            .then(function(data) {
                var entries = data.feed.entry || [];
                allPosts = entries.map(function(entry) {
                    var link = entry.link.find(function(l) { return l.rel === 'alternate'; });
                    return {
                        id: entry.id.$t,
                        title: entry.title.$t || 'Untitled',
                        snippet: entry.summary ? entry.summary.$t.substring(0, 150) : '',
                        url: link ? link.href : '#',
                        date: new Date(entry.published.$t).toLocaleDateString()
                    };
                });
            })
            .catch(function(error) {
                console.error('Error fetching posts:', error);
            });
    }

    function searchPosts(query) {
        if (!query || query.length < 2) {
            searchResults.innerHTML = '';
            return;
        }

        var term = query.toLowerCase();
        var results = allPosts.filter(function(post) {
            return post.title.toLowerCase().includes(term) || 
                   post.snippet.toLowerCase().includes(term);
        });

        results = results.slice(0, 10);

        if (results.length === 0) {
            searchResults.innerHTML = '<div class="no-results"><i class="fas fa-search text-4xl text-zinc-300 mb-2"></i><p>ކއްވެސް ނުފެނުނު</p></div>';
            return;
        }

        var html = '';
        results.forEach(function(post) {
            html += '<a href="' + post.url + '" class="search-result-item block">';
            html += '<h4>' + post.title + '</h4>';
            html += '<p>' + post.snippet + '</p>';
            html += '<span class="post-date">' + post.date + '</span>';
            html += '</a>';
        });

        searchResults.innerHTML = html;
    }

    if (searchInput) {
        searchInput.addEventListener('input', function() {
            searchPosts(this.value);
        });
    }

    // Share Functions
    window.sharePost = function(platform) {
        var url = encodeURIComponent(window.location.href);
        var title = encodeURIComponent(document.querySelector('h1') ? document.querySelector('h1').textContent : '');
        var shareUrls = {
            twitter: 'https://twitter.com/intent/tweet?url=' + url + '&text=' + title,
            facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + url,
            linkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + url,
            whatsapp: 'https://api.whatsapp.com/send?text=' + title + '%20-%20' + url
        };
        window.open(shareUrls[platform], '_blank', 'width=600,height=400');
    };

    window.copyLink = function() {
        navigator.clipboard.writeText(window.location.href).then(function() {
            var btn = event.target.closest('.share-icon-btn');
            var originalHtml = btn.innerHTML;
            btn.innerHTML = '<i class="fas fa-check text-teal-600"></i>';
            setTimeout(function() { btn.innerHTML = originalHtml; }, 2000);
        });
    };

    // Scroll to Top
    var scrollBtn = document.getElementById('scrollTopBtn');
    window.addEventListener('scroll', function() {
        if (window.scrollY > 500) {
            scrollBtn.classList.add('visible');
        } else {
            scrollBtn.classList.remove('visible');
        }
    });

    if (scrollBtn) {
        scrollBtn.addEventListener('click', function() {
            window.scrollTo({ top: 0, behavior: 'smooth' });
        });
    }

    // Fetch Categories
    function fetchCategories() {
        fetch('/feeds/posts/summary?alt=json&max-results=150')
            .then(function(response) { return response.json(); })
            .then(function(data) {
                var entries = data.feed.entry || [];
                var categoryMap = {};

                entries.forEach(function(entry) {
                    if (entry.category) {
                        entry.category.forEach(function(cat) {
                            var term = cat.term;
                            if (!categoryMap[term]) {
                                categoryMap[term] = { name: term };
                            }
                        });
                    }
                });

                var categories = Object.values(categoryMap);
                var navList = document.getElementById('navCategoryList');
                var mobileList = document.getElementById('mobileCategoryList');

                var navHtml = '';
                var mobileHtml = '';

                categories.forEach(function(cat) {
                    var catUrl = '/search/label/' + encodeURIComponent(cat.name);
                    navHtml += '<a href="' + catUrl + '">' + cat.name + '</a>';
                    mobileHtml += '<a href="' + catUrl + '" class="block text-sm text-zinc-600 hover:text-teal-600 transition">' + cat.name + '</a>';
                });

                if (navList) navList.innerHTML = navHtml;
                if (mobileList) mobileList.innerHTML = mobileHtml;
            })
            .catch(function(error) {
                console.error('Error fetching categories:', error);
            });
    }

    // Initialize
    fetchAllPosts();
    fetchCategories();
    calculateReadingTimes();
    parseExternalThumbnails();

})();
//
